minorLabels.$function:
function (date, scale, step) {
            var now = new Date();
            var ago = now - date;
            var divider;
            switch (scale) {
              case "millisecond":
                divider = 1;
                break;
              case "second":
                divider = 1000;
                break;
              case "minute":
                divider = 1000 * 60;
                break;
              case "hour":
                divider = 1000 * 60 * 60;
                break;
              case "day":
                divider = 1000 * 60 * 60 * 24;
                break;
              case "weekday":
                divider = 1000 * 60 * 60 * 24 * 7;
                break;
              case "month":
                divider = 1000 * 60 * 60 * 24 * 30;
                break;
              case "year":
                divider = 1000 * 60 * 60 * 24 * 365;
                break;
              default:
                return new Date(date);
            }
            return Math.round((ago * step) / divider) + " " + scale + "s ago";
          }

